effect.frag.content:
uniform float u_segments;
uniform float u_centerX;
uniform float u_centerY;
uniform float u_zoom;
const float TAU = 6.28318530718;
void main() {
  vec2 aspect = u_resolution / min(u_resolution.x, u_resolution.y);
  vec2 p = (v_uv - vec2(u_centerX, u_centerY)) * aspect;
  float radius = length(p) / u_zoom;
  float sector = TAU / u_segments;
  float angle = length(p) < 0.000001 ? 0.0 : atan(p.y, p.x);
  angle = abs(mod(angle + TAU * u_progress + sector * 0.5, sector) - sector * 0.5);
  vec2 uv = vec2(0.5) + radius * vec2(cos(angle), sin(angle)) / aspect;
  uv = 1.0 - abs(mod(uv, 2.0) - 1.0);
  fragColor = texture(u_source, uv);
}
